# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe PaymentProviders::RazorpayPaymentLinkService, "under the billing fence" do
  let(:company) { create(:company) }
  let(:client) { create(:client, company:, phone: "+919876543210") }
  let(:invoice) { create(:invoice, company:, client:, currency: "INR", status: "sent") }
  let(:provider) { instance_double(PaymentsProvider) }
  let(:razorpay_client) { instance_double(PaymentProviders::RazorpayClient) }

  before do
    allow(PaymentProviders::RazorpayClient).to receive(:new).and_return(razorpay_client)
    allow(razorpay_client).to receive(:create_payment_link)
  end

  # "Every invoice, line-item, invoice-tax and payment write, mobile-collection payments included,
  # gets 503 ownership_moving while handoff_step is set and writes nothing"
  # A link created and texted to the customer but never stored could be paid without the payment being recorded.
  it "creates no Razorpay link at the provider when a handoff refuses the payment link request" do
    payment_infos_before = invoice.reload.payment_infos
    TimekeepingOwnership.current.update!(handoff_step: "close_admission")

    service = described_class.new(invoice:, provider:, callback_url: "https://example.test/callback", notify_sms: true)

    expect { service.process }.to raise_error(Timekeeping::BillingFence::OwnershipMoving)
    expect(razorpay_client).not_to have_received(:create_payment_link)
    expect(invoice.reload.payment_infos).to eq(payment_infos_before)
  end
end
